div.div:
if (fastTick) begin
incSampleCounter = 1'b1;
if (halfBitTick) begin
clrSampleCounter = 1'b1;
end
end

if (fastTick) begin
incSampleCounter = 1'b1;
if (fullBitTick) begin
shiftEn = 1'b1;
incBitCounter = 1'b1;
clrSampleCounter = 1'b1;
end
end

if (fastTick) begin
incSampleCounter = 1'b1;
if (fullBitTick) begin
chkParity = 1'b1;
clrSampleCounter = 1'b1;
end
end

if (fastTick) begin
incSampleCounter = 1'b1;
if (fullBitTick) begin
clrSampleCounter = 1'b1;
if (fullFifo) begin
overRunError = 1'b1;
end else begin
writeEn = 1'b1;
end
end
end
